// === Tab: mySketch ===
// For the #WCCChallenge, theme: "sand."
// These things are amazing in real life!
// https://en.wikipedia.org/wiki/Ernst_Chladni
// https://paulbourke.net/geometry/chladni/
// Sand is placed on a vibrating plate, whose deflections create beautiful patterns.
// In this simulation, the sound frequencies have nothing to do with the distributions of the sand.
// (The real-world frequencies needed to make these patterns are not the most pleasant to listen to.)
// It would be neat to have a particle system here, and animate the transitions of the sand grains
// from one frequency pattern to the next. I suspect a shader could make that happen.

var osc1, osc2;
var m = 0
var n = 0;
var tm = 0;
var tn = 0;
var doubler = 0;
var index = -1;
var lim, dim;
var vol = 0.1;
var tvol = 0.1;
var amt = 0;

var combos = [{
	m: 1,
	n: 5,
	a: 261.63 //C
}, {
	m: 1,
	n: 4,
	a: 277.18 //Db
}, {
	m: 1,
	n: 3,
	a: 293.66 //D
}, {
	m: 1,
	n: 2,
	a: 311.13 //Eb
}, {
	m: 2,
	n: 5,
	a: 329.63 //E
}, {
	m: 2,
	n: 4,
	a: 369.99 //F#
}, {
	m: 2,
	n: 3,
	a: 392.0 //G
}, {
	m: 3,
	n: 5,
	a: 415.3 //Ab
}, {
	m: 3,
	n: 4,
	a: 466.16 //Bb
}, {
	m: 4,
	n: 5,
	a: 493.88 //B
}]

function setup() {
	lim = max(windowWidth, windowHeight);
	createCanvas(lim, lim);
	background(0)
	dim = lim * 0.9;
	osc1 = new p5.Oscillator('sawtooth');
	osc2 = new p5.Oscillator('sine');
	osc1.freq(110);
	osc1.amp(0.05);
	osc1.disconnect();
	osc1.start();
	osc2.start();
}

function draw() {
	m = lerp(m, tm, 0.1);
		n = lerp(n, tn, 0.1);

	osc2.amp(osc1); //creates distortion
	vol = lerp(vol, tvol, 0.1);
	fill(0, 2);
	noStroke();
	rect(0, 0, lim, lim);
	push();
	translate(lim / 20, lim / 20);
	let ang = PI * (1 + doubler);
	for (let i = 0; i < 300; i++) {
		let x = random(dim);
		let y = random(dim);
		let deflect = abs((cos(n * ang * x / dim) * cos(m * ang * y / dim)) - (cos(m * ang * x / dim) * cos(n * ang * y / dim)));
		let spread = (1 - deflect) ** 2;
		stroke(255, 255 * spread);
		if (m > 0) strokeWeight(spread * dim / 300);
		else strokeWeight(random(dim / 300));
		point(x, y);
	}
	pop();
	outputVolume(vol);
}

function mousePressed() {
	background(0);
	userStartAudio();
	index = (index + 1) % combos.length;
	if (tm > 0 && index == 0) doubler = 1 - doubler;
	osc2.freq(combos[index].a * (1 + doubler) / 2, 0.5);
	tm = combos[index].m;
	tn = combos[index].n;
}

function keyPressed() {
	if (keyCode == 32) tvol = 0.1 - tvol;
}
